<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');csrf_check();$id=(int)($_POST['id_kegiatan']??0);$password=(string)($_POST['password_baru']??'');if(strlen($password)<10){flash('danger','Password akun petugas minimal 10 karakter.');redirect('/admin/kegiatan/detail.php?id='.$id);}$q=$pdo->prepare("UPDATE users SET password=? WHERE id_kegiatan=? AND role_user='petugas'");$q->execute([password_hash($password,PASSWORD_DEFAULT),$id]);if($q->rowCount()){flash('success','Password akun petugas kegiatan berhasil diatur ulang.');}else{flash('danger','Akun petugas kegiatan tidak ditemukan atau password tidak berubah.');}redirect('/admin/kegiatan/detail.php?id='.$id);
